        const what = (vv[3] ?? vv[6] ?? '').trim();
        const prop =
          what === 'text'
            ? 'color'
            : what === 'border'
              ? 'border-color'
              : 'background-color';
        const group =
          prop === 'color'
            ? 'text'
            : prop === 'border-color'
              ? 'border'
              : 'background';
        const k1 = variantKey(part, vv[1]);
        const k2 = variantKey(part, vv[4]);
        const w2 = k2.replace(':', '=');
